sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here
    var logger = ["SPMReportingStatusData"];
    var query_filter = request.body.data.query;
    logger.push(query_filter);
    var table_col_data = request.body.data.column;
    var col_data_main_table = table_col_data.shift();
    var data = [];
    var col_meta_data = {};
    var col_data = [];
    for (let i of request.body.data.column) {
        var gr = new GlideRecord(i.table);
        for (let x of i.columns) {
            var el = gr.getElement(x);
            var eld = el.getED();
            var size = '110px';
            if (eld.getLength() > 1000)
                size = '372px';
            col_data.push('<style>.fixed_width {display:block;width:' + size + '}</style><span class="fixed_width">' + gr[x].getLabel() + '</span>');
            col_meta_data[i.table + '_' + x] = size;
        }
    }
    if (!query_filter){
		 return response.setBody({
            "column_data": col_data,
            "grid_data": []
        });
	} 
    gr = new GlideRecordSecure(col_data_main_table.table);
    gr.addEncodedQuery(query_filter);
    gr.addEncodedQuery('active=true');
    //gr.addEncodedQuery('primary_portfolio.sys_idIN738f2a981bca609076709759bc4bcb9c');
    gr.query();
    logger.push(gr.getRowCount());
    while (gr.next()) {
        let temp = [];
        for (let x of col_data_main_table.columns) {
            if (x == 'status')
                temp.push('<style>.fixed_width {display:block;width:110px;</style><span class="fixed_width"><span style="height: 15px;width: 15px;background-color:' + gr.getValue('status') + ';border-radius: 50%;display:block;"></span></span>');
            else {
                if (x == 'number') {
                    temp.push('<style>.fixed_width {display:block;width:' + col_meta_data[col_data_main_table.table + '_' + x] + '}</style><span class="fixed_width"><a target="_blank" href="' + gs.getProperty('glide.servlet.uri') + gr.getLink(false) + '">' + gr.getDisplayValue(x) || "" + '</a></span>');
                } else {
                    var t = gr.getDisplayValue(x) == null ? 'No Access' : (gr.getDisplayValue(x) || '');
                    temp.push('<style>.fixed_width {display:block;width:' + col_meta_data[col_data_main_table.table + '_' + x] + '}</style><span class="fixed_width">' + t + '</span>');
                }

            }

        }
        for (let y of table_col_data) {
            var related_record = getReleatedRecordData(y, gr);
            //gs.info(related_record);
            for (let z of y.columns) {
                let tempval = '';
                if (related_record != 'not_found')
                    tempval = related_record.getDisplayValue(z) || "";
                temp.push('<style>.fixed_width {display:block;width:' + col_meta_data[y.table + '_' + z] + '}</style><span class="fixed_width">' + tempval + '</span>');
            }

        }

        data.push(temp);
    }

    // gs.info(JSON.stringify(data));
    response.setBody({
        "column_data": col_data,
        "grid_data": data
    });

    function getReleatedRecordData(table_col_data, gr) {
        var status_gr = new GlideRecord(table_col_data.table);
        status_gr.addEncodedQuery(table_col_data.dependendent_field + '=' + gr.sys_id);
        status_gr.setLimit(1);
        status_gr.orderByDesc('as_on');
        status_gr.query();
        if (status_gr.next())
            return status_gr;
        else
            return "not_found";

    }

})(request, response);
